const j = $input.first().json;
const clean = (v) => String(v ?? '').trim().replace(/\s+/g, ' ');
const raw_input = { campaign_name: j.campaign_name ?? '', vertical: j.vertical ?? '', location_query: j.location_query ?? '', country_code: j.country_code ?? '', language: j.language ?? '', max_results_per_query: j.max_results_per_query ?? '', min_qualification_score: j.min_qualification_score ?? '', google_maps_query: j.google_maps_query ?? '' };
const campaign_name = clean(raw_input.campaign_name); const vertical = clean(raw_input.vertical); const location_query = clean(raw_input.location_query); const country_code = clean(raw_input.country_code).toUpperCase(); const language = clean(raw_input.language).toLowerCase() || 'en'; const google_maps_query = clean(raw_input.google_maps_query); const max_results_per_query = Math.max(1, Math.min(100, parseInt(raw_input.max_results_per_query || '50', 10))); const min_qualification_score = Math.max(0, Math.min(100, parseInt(raw_input.min_qualification_score || '60', 10))); if (!campaign_name || !vertical || !location_query || !country_code || !google_maps_query) throw new Error('Missing required campaign input.'); return [{ json: { ...j, raw_input, campaign_name, vertical, location_query, country_code, language, google_maps_query, max_results_per_query, min_qualification_score } }];

const c = $('Calculate Campaign Runtime').first().json;
const rawRows = $input.all().map(i => i.json || {}).filter(p => p.placeId || p.title);
const clean = (s) => String(s ?? '').trim();
const validRows = rawRows.filter(p => clean(p.placeId));

if (!validRows.length) {
  return [{ json: {
    no_results: true,
    campaign_id: c.campaign_id,
    campaign_name: c.campaign_name,
    invalid_google_maps_records: rawRows.length,
    no_results_reason: rawRows.length ? 'no_valid_place_id' : 'no_google_maps_results'
  } }];
}

const instagramProfile = (u) => {
  if (!u || !/instagram\.com/i.test(u)) return null;
  const m = String(u).match(/instagram\.com\/([^/?#]+)/i);
  return m ? `https://www.instagram.com/${m[1]}/` : null;
};

const invalidCount = rawRows.length - validRows.length;
return validRows.map(p => {
  const placeId = clean(p.placeId);
  const business = clean(p.title) || 'Unknown business';
  const address = clean(p.address) || null;
  const rawWebsite = clean(p.website) || null;
  const instagram_url = instagramProfile(rawWebsite);
  const website = instagram_url ? null : rawWebsite;
  const lead_key = `gmaps:${placeId}`;

  return { json: {
    no_results: false,
    campaign_id: c.campaign_id,
    campaign_name: c.campaign_name,
    vertical: c.vertical,
    country_code: clean(p.countryCode || c.country_code).toUpperCase(),
    language: c.language,
    min_qualification_score: c.min_qualification_score,
    source: 'google_maps_apify',
    source_place_id: placeId,
    lead_key,
    business_name: business,
    category_name: clean(p.categoryName) || null,
    address,
    city: clean(p.city) || null,
    phone: clean(p.phone) || null,
    website,
    google_maps_url: clean(p.url) || null,
    instagram_url,
    invalid_google_maps_records: invalidCount
  } };
});
